   "id": "z9e3f2c81",
   "sez": "mondo",
   "titolo": "Attacco hacker ai supermercati in Francia: refrigeratori spenti e milioni di danni",
   "orig": "Cyberattack on French supermarkets causes fires, millions in losses",
   "lead": "Centinaia di supermercati in tutta la Francia sono stati colpiti da un attacco informatico su vasta scala e senza precedenti che ha preso di mira gli impianti di refrigerazione. Gli hacker hanno innalzato le temperature dei frigoriferi, provocando incendi in diverse strutture, lo scongelamento e il deterioramento di tonnellate di alimenti surgelati e lasciando gli scaffali vuoti in tutto il Paese. I danni economici ammontano a milioni di euro, mentre l'episodio ha sollevato forti preoccupazioni riguardo alla sicurezza alimentare e alla tenuta delle infrastrutture commerciali sul territorio europeo.",
   "more": [
    "La refrigerazione centralizzata nella grande distribuzione si basa su reti informatiche connesse per regolare costantemente le temperature e preservare la catena del freddo. Un'intrusione telematica mirata può disattivare i controlli automatici di sicurezza termica, portando al surriscaldamento dei compressori e rendendo inutilizzabili grandi quantità di scorte alimentari deperibili."
   ],
