   "id": "z060a80e1",
   "sez": "mondo",
   "titolo": "La Nato pubblica i piani di difesa contro Mosca: pronti a combattere subito",
   "orig": "La sfida della Nato a Mosca: “Se qualcuno ci attacca pronti a combattere adesso”",
   "lead": "La Nato ha reso pubblico il proprio piano operativo in caso di aggressione al territorio dell'Alleanza, lanciando un chiaro messaggio di deterrenza verso Mosca. Il comandante supremo Grynkevich ha dichiarato che i Paesi alleati sono pronti a combattere immediatamente se attaccati. Il vertice militare ha assicurato che le forze congiunte interverranno per fermare qualunque aggressore e, se necessario, per distruggerlo impiegando armi convenzionali, ribadendo la determinazione a difendere i confini euroatlantici contro ogni possibile minaccia armata russa.",
   "more": [
    "Il principio di difesa collettiva della Nato vincola gli alleati a considerare un attacco contro uno di essi come un attacco diretto all'intera organizzazione. I piani operativi definiscono lo schieramento preventivo, i tempi di reazione immediata e le modalità di ingaggio convenzionale dei contingenti multinazionali lungo i confini orientali dell'Europa."
   ],
