   "id": "zfdf18e2c",
   "sez": "mondo",
   "titolo": "Agenti federali perquisiscono la casa a Washington della deputata Ilhan Omar",
   "orig": "US federal agents search home of Trump critic Ilhan Omar",
   "lead": "Gli agenti federali statunitensi hanno perquisito la residenza di Washington della deputata democratica Ilhan Omar, nota per le sue posizioni critiche nei confronti di Donald Trump. Il dipartimento di Giustizia ha confermato l'approvazione del mandato di perquisizione, spiegando che l'operazione rientra nel quadro di un'indagine federale attualmente in corso. Dal canto suo, la parlamentare ha contestato duramente l'iniziativa, definendo l'azione delle autorità come un tentativo deliberato di colpire e intimidire gli avversari politici dell'amministrazione.",
   "more": [
    "La Camera dei rappresentanti degli Stati Uniti ospita i legislatori federali, le cui residenze private possono essere perquisite dalle agenzie giudiziarie solo previa autorizzazione di un giudice federale e approvazione del dipartimento di Giustizia, garantendo il rispetto delle procedure legali previste per i funzionari pubblici eletti."
   ],
