   "id": "zd6497565",
   "sez": "mondo",
   "titolo": "Nepal: oltre cento escursionisti stranieri isolati dalle alluvioni a Gorkha",
   "orig": "More than 100 foreign trekkers stranded by floods in Nepal’s Gorkha region",
   "lead": "Oltre cento escursionisti stranieri sono rimasti bloccati nella regione nepalese di Gorkha a causa di improvvise inondazioni che hanno devastato l'area montana. Le alluvioni lampo hanno spazzato via abitazioni civili, abbattuto ponti e distrutto diverse sezioni del percorso escursionistico attorno al monte Manaslu. Le autorità locali hanno avviato un'operazione di soccorso per raggiungere gli escursionisti isolati e mettere in sicurezza i tratti compromessi, mentre si lavora per ripristinare i collegamenti lungo i sentieri d'alta quota danneggiati dalla violenza delle acque. Lo riferisce Al Jazeera.",
   "more": [
    "Il circuito escursionistico attorno al massiccio del Manaslu è una delle aree himalayane più frequentate da trekker internazionali nel Nepal centrale. I percorsi montani, caratterizzati da gole strette e ponti sospesi, sono particolarmente vulnerabili a smottamenti e colate di fango causati da forti precipitazioni monsoniche improvvise."
   ],
