   "titolo": "Ronaldo sventola la sciarpa saudita dopo la partita interrotta per allarme missilistico",
   "orig": "Ronaldo waves Saudi-flag scarf after match interrupted by missile alert",
   "lead": "Il calciatore portoghese Cristiano Ronaldo ha sventolato una sciarpa con la bandiera dell'Arabia Saudita al termine della partita vinta dalla sua squadra, l'Al Nassr. L'incontro di calcio era stato temporaneamente interrotto a causa di un allarme missilistico scattato nello spazio aereo circostante. Dopo la ripresa della gara e il fischio finale che ha sancito il successo del club saudita, il fuoriclasse ha celebrato la vittoria davanti ai tifosi compiendo questo gesto simbolico sul terreno di gioco. Lo riferisce Al Jazeera.",
