   "titolo": "Il premio Nobel per l'Economia 2026 assegnato agli statunitensi Robert Hall e Michael Woodford",
   "orig": "Nobel Prize in Economics goes to pair of US economists",
   "lead": "Gli economisti statunitensi Robert E. Hall e Michael Woodford hanno vinto il premio Nobel per l'Economia 2026. La Reale Accademia delle Scienze di Svezia ha conferito loro il prestigioso riconoscimento per aver sviluppato innovativi modelli macroeconomici che aiutano governi e banche centrali a gestire le fasi di espansione e recessione. Gli studi decennali dei due accademici hanno fornito strumenti fondamentali per attenuare i picchi e le flessioni dei cicli produttivi, venendo adottati dai ministeri delle Finanze e dagli istituti di emissione di tutto il mondo per stabilizzare i sistemi economici.",
   "more": [
    "Il premio della Banca di Svezia per le scienze economiche in memoria di Alfred Nobel riconosce contributi teorici ed empirici fondamentali. I modelli macroeconomici premiati permettono di analizzare come decisioni sui tassi di interesse e interventi di spesa pubblica influenzino l'inflazione, i consumi e i livelli di occupazione durante le fasi avverse del ciclo economico."
   ],
