   "id": "zbdcc920d",
   "sez": "spazio",
   "titolo": "India: scontro tra Elon Musk e Mukesh Ambani per il debutto di Starlink",
   "orig": "Why Elon Musk is taking on India's richest man over Starlink",
   "lead": "Elon Musk ha aperto un duro confronto pubblico con l'uomo più ricco dell'India, Mukesh Ambani, proprietario del colosso Reliance, per lo sbarco del servizio internet satellitare Starlink nel subcontinente. Nonostante abbia ottenuto alcune approvazioni preliminari, il progetto di Musk rimane bloccato in una complessa fase di stallo normativo, condizionato da questioni relative alla sicurezza nazionale, alla concorrenza commerciale e al clima generale per gli investimenti esteri nel Paese, scatenando polemiche dirette tra i due miliardari.",
   "more": [
    "Starlink offre connettività internet a banda larga sfruttando una costellazione di satelliti in orbita terrestre bassa, consentendo l'accesso alla rete anche nelle zone rurali o isolate. Nei mercati emergenti come quello indiano, l'ingresso di operatori satellitari esteri compete direttamente con le reti mobili terrestri controllate dai grandi gruppi di telecomunicazione locali."
   ],
