   "id": "z11dbd679",
   "sez": "cultura",
   "titolo": "La Tate Modern si trasforma in un'orchestra con la nuova opera di Tarek Atoui",
   "orig": "tarek atoui turns tate modern’s turbine hall into a giant experimental orchestra",
   "lead": "L'artista e compositore sonoro libanese Tarek Atoui ha trasformato la celebre Turbine Hall della Tate Modern di Londra in una gigantesca orchestra sperimentale. L'intervento fa parte dell'undicesima edizione della Hyundai Commission, intitolata «Hold», che propone una grande installazione multisensoriale composta da strumenti scultorei, performance musicali, tecnologie e ricerca sociale. L'opera d'arte è stata ideata per coinvolgere l'intero corpo dei visitatori attraverso vibrazioni e suoni, ridisegnando le particolari caratteristiche acustiche e spaziali dell'iconico spazio museale della capitale britannica.",
   "more": [
    "La Turbine Hall è il monumentale atrio della Tate Modern di Londra, ricavato all'interno di una centrale elettrica dismessa affacciata sul Tamigi. Grazie alle sue imponenti dimensioni verticali, l'ambiente ospita periodicamente installazioni artistiche temporanee su grande scala create appositamente da artisti internazionali per interagire con l'architettura industriale e con il pubblico."
   ],
