   "titolo": "Regno Unito: i sindacati chiedono di adeguare le scuole e spostare gli esami per il caldo",
   "orig": "Retrofit schools and consider moving exams to beat extreme heat, says teaching union leader",
   "lead": "Il segretario generale del National Education Union britannico, Daniel Kebede, ha proposto di riorganizzare gli orari scolastici, ristrutturare gli istituti e posticipare le sessioni di esame estive per proteggere studenti e docenti dalle ondate di calore estremo nel Regno Unito. Durante l'estate, le temperature nelle aule hanno superato i quaranta gradi, costringendo centinaia di migliaia di ragazzi a tornare a casa. L'organizzazione sindacale suggerisce di anticipare l'orario delle lezioni e allungare le pause estive per adattarsi alle mutate condizioni climatiche. Lo riferisce The Guardian.",
