   "titolo": "The Apothecary Diaries, svelato il cast dei pirati Kajadan nel nuovo film",
   "orig": "The Apothecary Diaries: The Late Lady's Treasure Film's New Video Unveils Kajadan Pirates' Cast",
   "lead": "La produzione del film d'animazione The Apothecary Diaries: The Late Lady's Treasure ha diffuso un nuovo filmato promozionale che presenta i componenti e i doppiatori dei pirati del gruppo Kaja-dan. Tra gli interpreti annunciati per la pellicola figurano gli attori Kenshō Ono, Ryōta Takeuchi e Jirō Saitō. Il lungometraggio animato farà il suo debutto nelle sale cinematografiche giapponesi a partire dall'11 dicembre, proseguendo l'espansione dell'universo narrativo della celebre serie che ha recentemente visto proseguire la trasmissione dei nuovi episodi televisivi.",
   "more": [
    "The Apothecary Diaries nasce come serie di light novel giapponesi ambientata in una corte imperiale fittizia, incentrata su una giovane speziale che risolve misteri medici e intrighi di palazzo. Il successo editoriale ha dato origine ad adattamenti manga e a una serie animata particolarmente apprezzata dal pubblico internazionale."
   ],
