   "id": "z8f646829",
   "sez": "adolescenti",
   "titolo": "Dirigenti scolastici a convegno a Roma sul futuro dell'istruzione con Valditara",
   "orig": "Dirigenti scolastici, il 13 e 14 ottobre il Convegno nazionale ANP sul futuro della scuola. Interviene Valditara, diretta streaming",
   "lead": "A Roma, presso il Cinema Barberini, si svolge il nono Convegno nazionale dell'Associazione Nazionale Presidi, intitolato “Identità in movimento”, dedicato a delineare il futuro del sistema scolastico. L'appuntamento vede la partecipazione e l'intervento del ministro dell'Istruzione e del Merito Giuseppe Valditara, con sessioni trasmesse in diretta streaming per consentire il confronto sulle trasformazioni didattiche, organizzative e formative necessarie per rispondere alle esigenze delle nuove generazioni e dell'intero corpo docente italiano.",
   "more": [
    "L'Associazione Nazionale Presidi rappresenta i dirigenti delle scuole statali italiane, occupandosi del coordinamento gestionale e dei modelli educativi. I convegni nazionali offrono ai vertici degli istituti un'occasione per discutere le riforme normative, l'innovazione metodologica e l'orientamento didattico per gli studenti."
   ],
