   "id": "z1e913ce3",
   "sez": "spazio",
   "titolo": "Solar Orbiter rintraccia l'origine delle inversioni magnetiche del vento solare",
   "orig": "Solar Orbiter tracks origin of mysterious magnetic switchbacks",
   "lead": "La sonda spaziale Solar Orbiter, guidata dall'Agenzia Spaziale Europea, ha attraversato una caratteristica piega a forma di S nel campo magnetico del vento solare, nota tecnicamente come switchback. Analizzando le particelle all'interno di questa struttura, gli strumenti di bordo sono riusciti a tracciare la loro origine fino alla superficie del Sole. La scoperta chiarisce i meccanismi del magnetismo solare, considerato il motore principale delle pericolose tempeste geomagnetiche che si propagano nello spazio interplanetario fino a colpire il campo protettivo della Terra.",
   "more": [
    "Solar Orbiter è una missione scientifica internazionale progettata per studiare da vicino la nostra stella e le dinamiche dell'eliosfera. Il vento solare è un flusso costante di particelle cariche emesse dal Sole, le cui variazioni possono disturbare le reti elettriche e le comunicazioni satellitari terrestri."
   ],
