   "sez": "salute",
   "titolo": "Mese del tumore al seno, campagne di sensibilizzazione e barriere nelle aree rurali",
   "orig": "‘STOP, THINK, and ACT Against Breast Cancer’",
   "lead": "In occasione del mese dedicato alla prevenzione del tumore al seno, la compagnia Alba in Bahrein ha promosso una sessione di sensibilizzazione all'insegna del motto mirato a fermarsi, riflettere e agire contro la patologia. L'iniziativa richiama le sfide sanitarie globali legate alla diagnosi precoce, messe in luce anche da recenti indagini sull'accesso alle cure nelle aree rurali di vari Paesi, dove le donne continuano a scontrarsi con ostacoli logistici ed economici per eseguire esami di screening essenziali, rendendo necessaria una formazione sanitaria attiva tutto l'anno.",
   "more": [
    "Il tumore della mammella è una delle neoplasie più diffuse nella popolazione femminile mondiale. La diagnosi precoce mediante mammografia ed ecografia consente di individuare le lesioni in fase iniziale, aumentando sensibilmente i tassi di sopravvivenza e riducendo l'invasività dei trattamenti chirurgici o terapeutici."
   ],
