   "lead": "Nel borgo di Cala d'Oliva, all'interno dell'ex scuola dell'isola dell'Asinara, la Locanda del Parco propone piatti a base di pescato del giorno e offre ospitalità in sei camere. La struttura ricettiva si trova a gestire un contesto isolato, segnato da collegamenti marittimi ridotti, immobili fatiscenti e carenza di infrastrutture di base, arrivando persino a doversi occupare della gestione dei servizi igienici pubblici dell'area per garantire accoglienza ai visitatori. Lo riferisce Gambero Rosso.",
