   "lead": "Il vice primo ministro russo Aleksandr Novak ha reso noto che i Paesi membri dell'Unione Europea hanno acquistato oltre 320 miliardi di dollari in idrocarburi provenienti dalla Russia dal 2022 a oggi. Di questa somma complessiva, 21,3 miliardi di dollari corrispondono alle forniture registrate nei primi nove mesi del 2026. Tali flussi commerciali si sono mantenuti nonostante l'introduzione delle numerose sanzioni economiche comunitarie collegate al conflitto bellico in territorio ucraino.",
