   "lead": "La Cina fornisce direttamente solo il 5% dei macchinari e dei materiali usati dall'industria statunitense dei microchip, ma controlla oltre il 90% di specifiche terre rare essenziali per la fabbricazione dei componenti. È quanto emerge da un rapporto della Semiconductor Industry Association, il quale rileva che, sebbene il 95% della spesa annua da quasi 27 miliardi di dollari dei produttori americani sia destinato ad aziende con sede in Stati Uniti, Europa e Giappone, la dipendenza dalle risorse cinesi rimane determinante.",
