   "lead": "È stato reso accessibile alla comunità scientifica e al pubblico il rapporto preliminare delle osservazioni lunari raccolte dall'equipaggio della missione Artemis II della Nasa. Partiti con il razzo Space Launch System, gli astronauti Reid Wiseman, Victor Glover, Christina Koch e Jeremy Hansen hanno condotto un viaggio di circa dieci giorni attorno alla Luna a bordo della navicella Orion. Le registrazioni vocali, i disegni, le fotografie e le annotazioni formano un archivio ora interamente disponibile per gli studi orbitali.",
