   "orig": "Eala stunned in Wuhan by No 217; Zverev ends year at No 1 after Alcaraz loses in Shanghai",
   "lead": "Al torneo Shanghai Masters Carlos Alcaraz è stato sconfitto a sorpresa dal belga Zizou Bergs con il punteggio di 7-5, 7-6. L'eliminazione in due set del tennista spagnolo ha matematicamente confermato il tedesco Alexander Zverev come numero uno mondiale di fine stagione nella classifica Atp. Nel circuito femminile, al Wuhan Open la testa di serie filippina Alexandra Eala ha subito una clamorosa battuta d'arresto al primo turno contro la qualificata cinese Shi Han, numero 217 del ranking.",
