   "orig": "Meeting highlights from the Committee for Veterinary Medicinal Products (CVMP) 6-8 October 2026",
   "lead": "Il Comitato per i medicinali veterinari dell'Agenzia europea per i medicinali, riunitosi tra il 6 e l'8 ottobre 2026 ad Amsterdam, ha espresso parere favorevole all'autorizzazione all'immissione in commercio per il vaccino Bovilis Lumpyvax. La decisione positiva degli esperti regolatori è stata adottata in circostanze eccezionali per contrastare la dermatite nodulare contagiosa nei bovini, concludendo la sessione di valutazione scientifica sulla sicurezza e sull'efficacia clinica del presidio. Lo riferisce Agenzia europea per i medicinali (Ema).",
