   "lead": "Il Museo Nazionale di Etnografia e Storia Naturale di Chisinau ospita l'inaugurazione dell'esposizione intitolata 'Architettura e identità: la casa tradizionale nel sud della Repubblica di Moldavia'. La rassegna culturale, inserita nel programma pubblico del 13 ottobre, intende valorizzare le tecniche costruttive vernacolari, i materiali e le peculiarità abitative tipiche dei villaggi meridionali del Paese, offrendo una testimonianza tangibile dell'eredità architettonica locale. Lo riferisce IPN (inglese).",
