   "id": "z63d4f402",
   "sez": "salute",
   "titolo": "L'Ema rende permanente il servizio di consulenza per le sperimentazioni cliniche",
   "orig": "Clinical trial applications advice pilot becomes permanent",
   "lead": "L'Agenzia europea per i medicinali ha annunciato che il progetto pilota di consulenza per le domande di sperimentazione clinica, sviluppato nell'ambito dell'iniziativa Accelerating Clinical Trials in the EU, diventerà permanente a partire da gennaio 2027. Il programma fornisce supporto e assistenza tecnica agli sponsor durante la fase di preparazione delle richieste formali di avvio delle sperimentazioni cliniche, con l'obiettivo di agevolare l'iter regolatorio e incentivare la ricerca biomedica all'interno dell'Unione Europea. Lo riferisce Agenzia europea per i medicinali (Ema).",
   "more": [
    "L'Agenzia europea per i medicinali è l'organismo dell'Unione Europea incaricato della valutazione scientifica, della supervisione e del controllo della sicurezza dei farmaci. Il coordinamento delle sperimentazioni cliniche garantisce che i test sui medicinali rispettino rigorosi standard etici e metodologici a tutela della salute dei pazienti."
   ],
