   "id": "z6e59200d",
   "sez": "mondo",
   "titolo": "L'amministrazione Trump stanzia 100 milioni di dollari per i ricercatori STEM statunitensi",
   "orig": "After his university cutbacks, Trump announces $100 million for STEM researchers",
   "lead": "L'amministrazione guidata da Donald Trump ha annunciato lo stanziamento di cento milioni di dollari destinati alla formazione di ricercatori nei settori scientifici e tecnologici STEM che siano cittadini statunitensi. Il provvedimento giunge dopo una serie di interventi promossi dallo stesso Trump che avevano imposto consistenti tagli ai fondi destinati alla ricerca universitaria negli Stati Uniti. I nuovi finanziamenti intendono canalizzare risorse mirate verso le discipline scientifiche, matematiche e ingegneristiche riservandole a studiosi in possesso della cittadinanza americana. Lo riferisce NPR – Istruzione.",
   "more": [
    "L'acronimo STEM identifica le discipline legate a scienza, tecnologia, ingegneria e matematica, considerate determinanti per la competitività economica e l'innovazione industriale. Negli Stati Uniti il finanziamento pubblico della ricerca accademica rappresenta storicamente il motore principale dello sviluppo scientifico e della formazione di specialisti altamente qualificati."
   ],
