   "sez": "mondo",
   "titolo": "Nuovi orologi nucleari e rilevazioni per svelare i segreti della materia oscura",
   "orig": "Scientists develop nuclear clock that could advance dark matter search",
   "lead": "Un gruppo internazionale di ricercatori ha realizzato il primo orologio nucleare funzionante basato sulla transizione energetica interna al nucleo atomico, aprendo la strada a strumenti di misurazione del tempo di nuova generazione in grado di testare le leggi fondamentali della fisica e favorire la ricerca sulla materia oscura. Per decenni i cronometri più precisi hanno sfruttato le transizioni elettroniche degli atomi. Contemporaneamente, gli scienziati impegnati nell'esperimento LZ ritengono di aver forse individuato i primi indizi tangibili di questa sostanza invisibile che costituisce gran parte del cosmo.",
   "more": [
    "La materia oscura è un'ipotetica forma di materia che non emette né riflette luce, la cui esistenza è dedotta dalle interazioni gravitazionali osservate su stelle e galassie. La misurazione ultraprecisa del tempo tramite tecnologie atomiche e nucleari offre ai fisici nuovi strumenti per testare le costanti cosmologiche e rivelare particelle finora inafferrabili."
   ],
