   "sez": "adolescenti",
   "titolo": "I college statunitensi lanciano corsi di laurea per influencer e intelligenza artificiale",
   "orig": "New career paths: Colleges now offer degrees in influencing and AI",
   "lead": "Numerosi college negli Stati Uniti hanno avviato corsi di laurea innovativi incentrati su settori emergenti come l'attività di influencer, l'intelligenza artificiale e le scienze sanitarie, con l'obiettivo di attirare studenti interessati a nuovi sbocchi professionali. Nel programma The Indicator viene analizzato il modo in cui gli atenei americani stanno ripensando i propri piani di studio universitari negli ultimi anni per adattarsi alle rapide trasformazioni del mercato del lavoro e alle richieste di competenze inedite provenienti dal mondo digitale. Lo riferisce NPR – Istruzione.",
   "more": [
    "L'evoluzione delle piattaforme social e delle tecnologie basate su intelligenza artificiale ha generato nuove professioni nell'economia digitale. Per rispondere alle preferenze delle nuove generazioni, gli istituti di istruzione superiore integrano materie tradizionali con percorsi formativi dedicati alla creazione di contenuti online, alla gestione dell'immagine e all'automazione informatica."
   ],
