   "id": "z8b285f76",
   "sez": "musica",
   "titolo": "Il jazzista Immanuel Wilkins vince il MacArthur Fellowship e racconta la storia afroamericana",
   "orig": "'Genius grant' winner Immanuel Wilkins explains how he weaves Black history into his music",
   "lead": "Il sassofonista e compositore statunitense Immanuel Wilkins, vincitore della prestigiosa borsa di studio MacArthur Fellowship 2026, nota popolarmente come premio per geni, ha illustrato come la storia afroamericana sia intimamente intessuta nella propria produzione musicale. L'artista ha spiegato il profondo impatto che il riconoscimento della fondazione avrà sull'evoluzione della sua arte e sulla libertà creativa dei suoi progetti futuri, confermando la centralità delle radici culturali della comunità nera nella composizione delle sue opere jazz contemporanee. Lo riferisce NPR – Musica.",
   "more": [
    "La MacArthur Fellowship è un prestigioso riconoscimento concesso annualmente a cittadini o residenti statunitensi che abbiano dimostrato straordinaria originalità e dedizione nel proprio lavoro. La borsa, erogata senza vincoli d'uso, consente ad artisti e studiosi di perseguire liberamente la propria ricerca espressiva e culturale."
   ],
